query:
mutation ChangeCartConfiguredItem($command: InputChangeCartConfiguredItemType!) {
  changeCartConfiguredItem(command: $command) {
    ...fullCart
    __typename
  }
}

fragment cartId on CartType {
  id
  __typename
}

fragment shortLineItem on LineItemType {
  id
  sku
  quantity
  productId
  currencyCode
  __typename
}

fragment validationError on ValidationErrorType {
  errorCode
  errorMessage
  errorParameters {
    key
    value
    __typename
